package negocio;
import java.time.LocalDateTime;
public class InvitacionComunidad { private long id,perfilEmisorId,perfilDestinatarioId,version; private ObjetivoInvitacionComunidad objetivo; private EstadoInvitacionComunidad estado=EstadoInvitacionComunidad.PENDIENTE; private String mensaje; private LocalDateTime fechaInvitacion,fechaResolucion,fechaExpiracion; public long getId(){return id;} public void setId(long v){id=v;} public long getPerfilEmisorId(){return perfilEmisorId;} public void setPerfilEmisorId(long v){perfilEmisorId=v;} public long getPerfilDestinatarioId(){return perfilDestinatarioId;} public void setPerfilDestinatarioId(long v){perfilDestinatarioId=v;} public ObjetivoInvitacionComunidad getObjetivo(){return objetivo;} public void setObjetivo(ObjetivoInvitacionComunidad v){objetivo=v;} public EstadoInvitacionComunidad getEstado(){return estado;} public void setEstado(EstadoInvitacionComunidad v){estado=v;} public String getMensaje(){return mensaje;} public void setMensaje(String v){mensaje=v;} public LocalDateTime getFechaInvitacion(){return fechaInvitacion;} public void setFechaInvitacion(LocalDateTime v){fechaInvitacion=v;} public LocalDateTime getFechaResolucion(){return fechaResolucion;} public void setFechaResolucion(LocalDateTime v){fechaResolucion=v;} public LocalDateTime getFechaExpiracion(){return fechaExpiracion;} public void setFechaExpiracion(LocalDateTime v){fechaExpiracion=v;} public long getVersion(){return version;} public void setVersion(long v){version=v;} public void validar(){if(perfilEmisorId<=0||perfilDestinatarioId<=0||perfilEmisorId==perfilDestinatarioId||objetivo==null||estado==null||fechaInvitacion==null||fechaExpiracion==null)throw new IllegalArgumentException("La invitacion de Comunidad es incompleta.");if(mensaje!=null&&mensaje.length()>300)throw new IllegalArgumentException("El mensaje no puede superar 300 caracteres.");}}
